<div class="tw"><table><tr><th>Month</th><?php if (empty($own)): ?><th>Customer</th><?php endif; ?><th>Units</th><th>Total</th><th>Paid</th><th>Due</th><th>Status</th><th>Actions</th></tr>
<?php foreach ($rows as $b): $open = in_array($b['status'], ['Unpaid', 'Partially Paid'], true); ?><tr><td><?= e($b['billing_month']) ?></td><?php if (empty($own)): ?><td><?= e($b['full_name']) ?> <small class="muted"><?= e($b['meter_no']) ?></small></td><?php endif; ?><td><?= e($b['units_used']) ?></td><td><?= e(money($b['total_amount'])) ?></td><td><?= e(money($b['amount_paid'])) ?></td><td><?= e($b['due_date']) ?></td><td><?= badge($b['status']) ?></td>
<td class="acts2"><?= (!empty($own) && $open) ? act_link('ok', 'Pay Now', url('bills/show', ['id' => $b['bill_id']])) : act_link('view', 'View', url('bills/show', ['id' => $b['bill_id']])) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="muted">No bills found.</td></tr><?php endif; ?></table></div>
